    """Reconstruct a repeated n-by-n motif tiled on an n-by-n macro-grid.

    A full color-3 row/column masks one macro strip. The motif itself gives
    which macro tiles are occupied; each occupied tile gets an 8 marker at
    the motif cell corresponding to that tile's macro coordinates.
    """
    h, w = len(grid), len(grid[0])
    n = None
    # The grid has n motif cells per tile and one zero gap between tiles:
    # dimension = n*n + (n-1).
    for k in range(1, min(h, w) + 1):
        if k * k + k - 1 == h and k * k + k - 1 == w:
            n = k
            break
    if n is None:
        raise ValueError("expected square grid tiled by square motifs")
    motif = None
    # Use an intact non-separator tile as the motif source.
