 "content": "from collections import Counter


def transform(grid):
    """Reconstruct repeated motif tiles hidden by a full separator band.

    The macro-grid is n by n, each tile is n by n, with one-cell zero gutters.
    A tile is present exactly when the motif's macro-coordinate cell is 2;
    within every present tile that coordinate is highlighted as 8.
    """
    h, w = len(grid), len(grid[0])
    if h != w:
        raise ValueError("expected square input")
    n = next((k for k in range(1, h + 1) if k * k + k - 1 == h), None)
    if n is None:
        raise ValueError("unexpected tiled-grid dimensions")

    # A tile containing the complete motif is a nonempty n x n block of 0/2.
    blocks = []
    for tr in range(n):
        for tc in range(n):
            r0, c0 = tr * (n + 1), tc * (n + 1)
            block = tuple(tuple(grid[r0+i][c0:c0+n]) for i in range(n))
            if all(v in (0, 2) for row in block for v in row) and any(v == 2 for row in block for v in row):
                blocks.append(block)
    if not blocks:
        raise ValueError("no unmasked motif tile found")
    motif = Counter(blocks).most_common(1)[0][0]

    out = [[0] * w for _ in range(h)]
    for tr in range(n):
        for tc in range(n):
            if motif[tr][tc] != 2:
                continue
            r0, c0 = tr * (n + 1), tc * (n + 1)
            for i in range(n):
                for j in range(n):
                    if motif[i][j] == 2:
                        out[r0+i][c0+j] = 2
            out[r0+tr][c0+tc] = 8
    return out


